{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 음주 금지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제22조의3에 따르면 시장은 어린이공원을 금주구역으로 지정할 수 있습니다. 따라서 모든 공원이 자동으로 금주구역인 것은 아니고, 시장이 금주구역으로 지정한 어린이공원에서만 음주가 금지됩니다. 금주구역에서 음주를 하면 같은 조례 제23조 제4항에 따라 10만원의 과태료가 부과됩니다.",
          "b_ids": "도시공원:제22조의3, 도시공원:제23조제4항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "모든 공원이 금주구역인지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제22조의3은 시장이 어린이공원을 금주구역으로 지정할 수 있다고 정하고 있을 뿐, 모든 공원을 금주구역으로 정하지는 않습니다. 따라서 모든 공원이 금주구역인 것은 아니며, 금주구역 지정 여부는 개별 공원의 지정 여부에 따라 달라집니다.",
          "b_ids": "도시공원:제22조의3"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
